INSERT INTO `products` (`id`, `slug`, `name`, `brand`, `category_slug`, `subcategory`, `description`, `brand_story`, `origin`, `country`, `abv`, `volume_ml`, `price`, `compare_at_price`, `rating`, `review_count`, `tasting_notes`, `food_pairings`, `cocktails`, `images`, `color`, `accent_color`, `label_color`, `bottle_height`, `is_premium`, `is_imported`, `tags`, `nutrition`, `glb_url`, `usdz_url`, `is_custom`, `created_at`, `updated_at`) VALUES
  ('mk-buffalo-trace', 'buffalo-trace-bourbon', 'Buffalo Trace Kentucky Straight Bourbon', 'Buffalo Trace', 'bourbon', 'Kentucky Straight', 'Flagship Kentucky bourbon with sweet corn, vanilla, and a gentle oak spice. An everyday pour that still feels like a treat neat or in an Old Fashioned.', 'Buffalo Trace Distillery on the Kentucky River has been making whiskey for more than 200 years — this bottle is the house signature.', 'Frankfort, Kentucky', 'USA', 45, 750, 27, 32, 4.7, 6120, '["Vanilla","Brown sugar","Oak","Mint"]', '["BBQ brisket","Pecan pie","Sharp cheddar"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/buffalo-trace-bourbon.jpg"]', '#4a2c14', '#B87333', '#120e08', 1.08, 0, 0, '["kentucky","everyday","cocktail"]', NULL, '/models/bottles/buffalo-trace-bourbon.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-makers-mark', 'makers-mark-bourbon', 'Maker''s Mark Kentucky Straight Bourbon', 'Maker''s Mark', 'bourbon', 'Wheated Bourbon', 'Wheated bourbon with a red-wax seal. Soft caramel, vanilla, and baking spice without the rye bite — easy sipping and a classic mixer.', 'Maker''s Mark still rotates barrels by hand in Loretto and dips every bottle in that trademark red wax.', 'Loretto, Kentucky', 'USA', 45, 750, 28, 33, 4.6, 5400, '["Caramel","Vanilla","Soft wheat","Oak"]', '["Ham","Apple tart","Mild cheddar"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/makers-mark-bourbon.webp"]', '#4a2c14', '#B87333', '#120e08', 1.08, 0, 0, '["wheated","everyday","gift"]', NULL, '/models/bottles/makers-mark-bourbon.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-jim-beam', 'jim-beam-white-label', 'Jim Beam White Label Bourbon', 'Jim Beam', 'bourbon', 'Kentucky Straight', 'The world''s most poured bourbon — light caramel, corn sweetness, and a clean finish. Built for highballs, cola, and weeknight mixing.', 'Seven generations of the Beam family have made this recipe the default bourbon behind American bars.', 'Clermont, Kentucky', 'USA', 40, 750, 16, NULL, 4.2, 8900, '["Corn","Light caramel","Oak","Spice"]', '["Burgers","Pretzels","Cola"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/jim-beam-white-label.jpg"]', '#4a2c14', '#B87333', '#120e08', 1.08, 0, 0, '["everyday","value","mixer"]', NULL, '/models/bottles/jim-beam-white-label.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-jim-beam-black', 'jim-beam-black-7-year', 'Jim Beam Black Extra-Aged 7 Year', 'Jim Beam', 'bourbon', 'Extra-Aged', 'Seven years in charred oak gives Black more toasted sugar, vanilla, and a rounder sip than White Label — still priced for regular rotation.', 'Jim Beam Black is the extra-aged expression of the Beam family recipe, aimed at drinkers who want more barrel without collector prices.', 'Clermont, Kentucky', 'USA', 43, 750, 26, NULL, 4.4, 2100, '["Toasted oak","Vanilla","Dark caramel","Spice"]', '["Smoked pork","Chocolate","Pecans"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/jim-beam-black-7-year.webp"]', '#4a2c14', '#B87333', '#120e08', 1.08, 0, 0, '["aged","sipping","value"]', NULL, '/models/bottles/jim-beam-black-7-year.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-bulleit', 'bulleit-bourbon', 'Bulleit Bourbon', 'Bulleit', 'bourbon', 'High-Rye Bourbon', 'High-rye bourbon in a flask-inspired bottle. Orange peel, spice, and dry oak make it a bartender favorite for Manhattans and Old Fashioneds.', 'Bulleit revived a frontier-era high-rye mash bill and became a modern cocktail-bar staple.', 'Lawrenceburg, Kentucky', 'USA', 45, 750, 25, NULL, 4.5, 4300, '["Rye spice","Orange peel","Vanilla","Dry oak"]', '["Steak","Dark chocolate","Charcuterie"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/bulleit-bourbon.png"]', '#4a2c14', '#B87333', '#120e08', 1.08, 0, 0, '["high-rye","cocktail","everyday"]', NULL, '/models/bottles/bulleit-bourbon.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-woodford', 'woodford-reserve-bourbon', 'Woodford Reserve Distiller''s Select', 'Woodford Reserve', 'bourbon', 'Small Batch', 'Small-batch Kentucky bourbon with dried fruit, toasted oak, and baking spice. A step-up sipper that still works in a stirred cocktail.', 'Woodford Reserve is distilled at the historic Labrot & Graham site in Versailles, Kentucky, using copper pot stills alongside column stills.', 'Versailles, Kentucky', 'USA', 45.2, 750, 33, NULL, 4.6, 3800, '["Dried fruit","Toasted oak","Spice","Honey"]', '["Roast chicken","Apple pie","Blue cheese"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/woodford-reserve-bourbon.webp"]', '#4a2c14', '#B87333', '#120e08', 1.08, 0, 0, '["small-batch","sipping","gift"]', NULL, '/models/bottles/woodford-reserve-bourbon.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-wild-turkey-101', 'wild-turkey-101-bourbon', 'Wild Turkey 101 Bourbon', 'Wild Turkey', 'bourbon', 'Bottled-in-Bond Style', 'Bold 101-proof Kentucky bourbon — rich caramel, leather, and spice. Holds up to ice and mixers without disappearing.', 'Wild Turkey has bottled this higher-proof house style for decades; it''s the workhorse of many serious home bars.', 'Lawrenceburg, Kentucky', 'USA', 50.5, 750, 22, NULL, 4.6, 4700, '["Caramel","Leather","Spice","Oak"]', '["Ribs","Chili","Dark chocolate"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/wild-turkey-101-bourbon.webp"]', '#4a2c14', '#B87333', '#120e08', 1.08, 0, 0, '["high-proof","everyday","cocktail"]', NULL, '/models/bottles/wild-turkey-101-bourbon.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-knob-creek-9', 'knob-creek-9-year', 'Knob Creek 9 Year Bourbon', 'Knob Creek', 'bourbon', 'Small Batch', 'Nine-year small-batch bourbon with deep oak, toasted nuts, and maple. Full-bodied enough to drink neat.', 'Knob Creek was created to recall pre-Prohibition, longer-aged bourbon at a higher proof.', 'Clermont, Kentucky', 'USA', 50, 750, 42, NULL, 4.7, 2900, '["Maple","Toasted oak","Nuts","Cocoa"]', '["Ribeye","Pecan pie","Cigar lounge"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/knob-creek-9-year.webp"]', '#4a2c14', '#B87333', '#120e08', 1.08, 1, 0, '["small-batch","sipping","gift"]', NULL, '/models/bottles/knob-creek-9-year.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-blantons', 'blantons-single-barrel', 'Blanton''s Single Barrel Bourbon', 'Blanton''s', 'bourbon', 'Single Barrel', 'The original single-barrel bourbon. Each dump is unique — typically orange, caramel, and polished oak with a horse-stopper bottle that collectors hunt.', 'Named for Colonel Albert B. Blanton, this was the first widely sold single-barrel bourbon and remains an allocated favorite.', 'Frankfort, Kentucky', 'USA', 46.5, 750, 80, 99, 4.8, 2100, '["Orange","Caramel","Oak","Honey"]', '["Steak","Dark chocolate","Cheese board"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/blantons-single-barrel.jpg"]', '#4a2c14', '#B87333', '#120e08', 1.08, 1, 0, '["single-barrel","allocated","gift","collector"]', NULL, '/models/bottles/blantons-single-barrel.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-weller-antique', 'weller-antique-107', 'W.L. Weller Antique 107', 'W.L. Weller', 'bourbon', 'Wheated Bourbon', 'Wheated bourbon bottled at 107 proof. Soft grain sweetness with heat and cinnamon — a collector pour when you can find it.', 'Weller is Buffalo Trace''s wheated line, the same mash-bill family as Pappy Van Winkle, bottled more accessibly.', 'Frankfort, Kentucky', 'USA', 53.5, 750, 99, NULL, 4.8, 980, '["Wheat","Cinnamon","Caramel","Oak"]', '["Pecan pie","Ham","Dark chocolate"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/weller-antique-107.jpg"]', '#4a2c14', '#B87333', '#120e08', 1.08, 1, 0, '["wheated","allocated","sipping"]', NULL, '/models/bottles/weller-antique-107.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-penelope-bs', 'penelope-barrel-strength-bourbon', 'Penelope Barrel Strength Bourbon', 'Penelope', 'bourbon', 'Barrel Strength', 'Uncut wheated bourbon bottled at cask strength. Big vanilla, orchard fruit, and heat — add a drop of water if you want it to open.', 'Penelope Bourbon is named for the founders'' daughter and built around a four-grain wheated mash bill.', 'Kentucky', 'USA', 57, 750, 52, NULL, 4.6, 410, '["Vanilla","Orchard fruit","Oak","Heat"]', '["Steak","Chocolate","Nuts"]', '[{"name":"Old Fashioned","ingredients":["60ml bourbon","5ml demerara","2 dashes Angostura","Orange peel"],"method":"Stir over ice, strain over a large cube, express peel."},{"name":"Bourbon Highball","ingredients":["50ml bourbon","Soda","Lemon"],"method":"Build over ice in a tall glass."}]', '["/products/market/penelope-barrel-strength-bourbon.png"]', '#4a2c14', '#B87333', '#120e08', 1.08, 1, 0, '["cask-strength","wheated","sipping"]', NULL, '/models/bottles/penelope-barrel-strength-bourbon.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-jameson', 'jameson-irish-whiskey', 'Jameson Irish Whiskey', 'Jameson', 'whiskey', 'Irish Blend', 'Triple-distilled Irish blend — light spice, vanilla, and a smooth finish. The default pour for whiskey-ginger and Irish coffee.', 'Jameson has been distilled in Ireland since 1780 and remains the world''s most recognized Irish whiskey.', 'Cork, Ireland', 'Ireland', 40, 750, 28, NULL, 4.5, 7200, '["Vanilla","Spice","Nutty","Smooth"]', '["Fish and chips","Cheddar","Apple dessert"]', '[{"name":"Whiskey Sour","ingredients":["50ml whiskey","25ml lemon","15ml syrup"],"method":"Shake hard, strain over ice."},{"name":"Highball","ingredients":["50ml whiskey","Ginger ale"],"method":"Build over ice."}]', '["/products/market/jameson-irish-whiskey.webp"]', '#3d2818', '#C9A962', '#0f0a05', 1.1, 0, 1, '["irish","everyday","mixer"]', NULL, '/models/bottles/jameson-irish-whiskey.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-crown-royal', 'crown-royal-blended', 'Crown Royal Blended Canadian Whisky', 'Crown Royal', 'whiskey', 'Canadian Blend', 'Velvet Canadian blend in the purple bag. Soft vanilla, rye spice, and a round finish — a party-pour classic.', 'Created in 1939 to honor a royal visit to Canada, Crown Royal is still blended in Gimli, Manitoba.', 'Gimli, Manitoba', 'Canada', 40, 750, 29, NULL, 4.4, 5600, '["Vanilla","Rye spice","Caramel","Smooth"]', '["Smoked meat","Apple pie","Cola"]', '[{"name":"Whiskey Sour","ingredients":["50ml whiskey","25ml lemon","15ml syrup"],"method":"Shake hard, strain over ice."},{"name":"Highball","ingredients":["50ml whiskey","Ginger ale"],"method":"Build over ice."}]', '["/products/market/crown-royal-blended.jpg"]', '#3d2818', '#C9A962', '#0f0a05', 1.1, 0, 1, '["canadian","everyday","gift"]', NULL, '/models/bottles/crown-royal-blended.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-teeling', 'teeling-small-batch', 'Teeling Small Batch Irish Whiskey', 'Teeling', 'whiskey', 'Irish Blend', 'Dublin whiskey finished in rum casks — tropical fruit over classic Irish malt. A step up from entry blends without collector pricing.', 'The Teeling family revived whiskey distilling in Dublin city and built this rum-cask small batch as their calling card.', 'Dublin, Ireland', 'Ireland', 46, 750, 34, NULL, 4.5, 890, '["Tropical fruit","Spice","Vanilla","Malt"]', '["Pork","Fruit tart","Cheese"]', '[{"name":"Whiskey Sour","ingredients":["50ml whiskey","25ml lemon","15ml syrup"],"method":"Shake hard, strain over ice."},{"name":"Highball","ingredients":["50ml whiskey","Ginger ale"],"method":"Build over ice."}]', '["/products/market/teeling-small-batch.png"]', '#3d2818', '#C9A962', '#0f0a05', 1.1, 0, 1, '["irish","rum-cask","sipping"]', NULL, '/models/bottles/teeling-small-batch.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-toki', 'suntory-toki-japanese-whisky', 'Suntory Toki Japanese Whisky', 'Suntory', 'whiskey', 'Japanese Blend', 'Light, crisp Japanese blend built for highballs — green grape, white pepper, and a clean finish.', 'Suntory blends malt and grain from Yamazaki, Hakushu, and Chita for Toki, their modern mixing whisky.', 'Japan', 'Japan', 43, 750, 36, NULL, 4.4, 2100, '["Green grape","Honey","White pepper","Oak"]', '["Sushi","Tempura","Green apple"]', '[{"name":"Whiskey Sour","ingredients":["50ml whiskey","25ml lemon","15ml syrup"],"method":"Shake hard, strain over ice."},{"name":"Highball","ingredients":["50ml whiskey","Ginger ale"],"method":"Build over ice."}]', '["/products/market/suntory-toki-japanese-whisky.png"]', '#3d2818', '#C9A962', '#0f0a05', 1.1, 0, 1, '["japanese","highball","imported"]', NULL, '/models/bottles/suntory-toki-japanese-whisky.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-hibiki', 'hibiki-japanese-harmony', 'Hibiki Japanese Harmony', 'Hibiki', 'whiskey', 'Japanese Blend', 'Suntory''s flagship harmony blend — honey, orange peel, and sandalwood in a 24-faceted bottle that reads as a gift before you pour.', 'Hibiki is Suntory''s prestige blend, drawing malt and grain from across the company''s Japanese distilleries.', 'Japan', 'Japan', 43, 750, 95, NULL, 4.8, 1400, '["Honey","Orange peel","Oak","Sandalwood"]', '["Sashimi","Almonds","Mild cheese"]', '[{"name":"Whiskey Sour","ingredients":["50ml whiskey","25ml lemon","15ml syrup"],"method":"Shake hard, strain over ice."},{"name":"Highball","ingredients":["50ml whiskey","Ginger ale"],"method":"Build over ice."}]', '["/products/market/hibiki-japanese-harmony.jpg"]', '#3d2818', '#C9A962', '#0f0a05', 1.1, 1, 1, '["japanese","gift","premium"]', NULL, '/models/bottles/hibiki-japanese-harmony.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-whistlepig-12', 'whistlepig-12-old-world-rye', 'WhistlePig 12 Year Old World Rye', 'WhistlePig', 'whiskey', 'Rye Whiskey', 'Twelve-year rye finished in French, Port, and Sauternes casks. Spice, dried fruit, and a long sweet-oak finish.', 'WhistlePig built its name on high-rye whiskey from Shoreham, Vermont, with European finishing casks for the Old World line.', 'Vermont', 'USA', 43, 750, 149, NULL, 4.7, 520, '["Rye spice","Dried fruit","Port","Oak"]', '["Steak","Blue cheese","Dark chocolate"]', '[{"name":"Whiskey Sour","ingredients":["50ml whiskey","25ml lemon","15ml syrup"],"method":"Shake hard, strain over ice."},{"name":"Highball","ingredients":["50ml whiskey","Ginger ale"],"method":"Build over ice."}]', '["/products/market/whistlepig-12-old-world-rye.webp"]', '#3d2818', '#C9A962', '#0f0a05', 1.1, 1, 0, '["rye","gift","sipping"]', NULL, '/models/bottles/whistlepig-12-old-world-rye.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-rittenhouse', 'rittenhouse-rye-bonded', 'Rittenhouse Straight Rye Bottled in Bond', 'Rittenhouse', 'whiskey', 'Rye Whiskey', '100-proof bonded rye — pepper, cinnamon, and dry oak. The workhorse rye for Sazeracs and Manhattans.', 'Rittenhouse is Heaven Hill''s bottled-in-bond rye, a bartender staple for classic whiskey cocktails.', 'Kentucky', 'USA', 50, 750, 28, NULL, 4.6, 1800, '["Pepper","Cinnamon","Oak","Dill"]', '["Pastrami","Pickles","Dark chocolate"]', '[{"name":"Whiskey Sour","ingredients":["50ml whiskey","25ml lemon","15ml syrup"],"method":"Shake hard, strain over ice."},{"name":"Highball","ingredients":["50ml whiskey","Ginger ale"],"method":"Build over ice."}]', '["/products/market/rittenhouse-rye-bonded.webp"]', '#3d2818', '#C9A962', '#0f0a05', 1.1, 0, 0, '["rye","bonded","cocktail"]', NULL, '/models/bottles/rittenhouse-rye-bonded.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-jw-black', 'johnnie-walker-black-label', 'Johnnie Walker Black Label', 'Johnnie Walker', 'scotch', 'Blended Scotch', '12-year blended Scotch with smoke, dried fruit, and vanilla. The world''s default ''good Scotch'' for gifts and mixing.', 'Johnnie Walker Black has been the blend''s prestige everyday expression since the early 20th century.', 'Scotland', 'Scotland', 40, 750, 36, NULL, 4.6, 8100, '["Smoke","Dried fruit","Vanilla","Oak"]', '["Smoked salmon","Dark chocolate","Steak"]', '[{"name":"Rob Roy","ingredients":["50ml scotch","25ml sweet vermouth","Dash bitters"],"method":"Stir, strain into a coupe, cherry garnish."},{"name":"Scotch & Soda","ingredients":["50ml scotch","Soda","Lemon twist"],"method":"Build over ice."}]', '["/products/market/johnnie-walker-black-label.jpg"]', '#5c3a1e', '#C9A962', '#0f0a05', 1.12, 0, 1, '["blend","gift","everyday"]', NULL, '/models/bottles/johnnie-walker-black-label.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
