  ('mk-caymus-cab', 'caymus-cabernet-sauvignon', 'Caymus Cabernet Sauvignon', 'Caymus', 'wine', 'Cabernet Sauvignon', 'Napa cabernet with ripe blackberry, cocoa, and plush tannins. A steakhouse classic.', 'The Wagner family has made Caymus in Rutherford since 1972; the cabernet is their signature.', 'Napa Valley, California', 'USA', 14.6, 750, 82, NULL, 4.7, 1600, '["Blackberry","Cocoa","Vanilla","Oak"]', '["Ribeye","Lamb","Blue cheese"]', '[{"name":"Wine spritz","ingredients":["90ml wine","Soda","Citrus"],"method":"Build over ice in a wine glass."}]', '["/products/market/caymus-cabernet-sauvignon.png"]', '#5a1820', '#722F37', '#1a080c', 1.18, 1, 0, '["napa","cabernet","gift"]', NULL, '/models/bottles/caymus-cabernet-sauvignon.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-veuve', 'veuve-clicquot-yellow-label', 'Veuve Clicquot Brut Yellow Label', 'Veuve Clicquot', 'champagne', 'Brut Champagne', 'Pinot-led Champagne with brioche, citrus, and a firm mousse. The yellow label is the celebration default.', 'Veuve Clicquot, guided by Madame Clicquot in the 19th century, remains one of Champagne''s most recognized houses.', 'Reims, France', 'France', 12, 750, 59, NULL, 4.7, 3800, '["Brioche","Citrus","Apple","Toast"]', '["Oysters","Fried chicken","Canapés"]', '[{"name":"French 75","ingredients":["30ml gin","15ml lemon","10ml syrup","Champagne"],"method":"Shake base, strain into a flute, top with bubbles."},{"name":"Kir Royale","ingredients":["15ml crème de cassis","Champagne"],"method":"Pour cassis in a flute, top with champagne."}]', '["/products/market/veuve-clicquot-yellow-label.jpg"]', '#f3ead2', '#F5E6C8', '#2a2418', 1.2, 1, 1, '["champagne","brut","gift"]', NULL, '/models/bottles/veuve-clicquot-yellow-label.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-moet', 'moet-chandon-imperial-brut', 'Moët & Chandon Impérial Brut', 'Moët & Chandon', 'champagne', 'Brut Champagne', 'Bright, apple-and-citrus Champagne with a lively mousse. The house''s global non-vintage.', 'Moët & Chandon has been the Champagne of celebrations since the 18th century; Impérial is the flagship NV.', 'Épernay, France', 'France', 12, 750, 46, NULL, 4.5, 2900, '["Apple","Citrus","Brioche","Floral"]', '["Oysters","Sushi","Fruit"]', '[{"name":"French 75","ingredients":["30ml gin","15ml lemon","10ml syrup","Champagne"],"method":"Shake base, strain into a flute, top with bubbles."},{"name":"Kir Royale","ingredients":["15ml crème de cassis","Champagne"],"method":"Pour cassis in a flute, top with champagne."}]', '["/products/market/moet-chandon-imperial-brut.jpg"]', '#f3ead2', '#F5E6C8', '#2a2418', 1.2, 0, 1, '["champagne","brut","celebration"]', NULL, '/models/bottles/moet-chandon-imperial-brut.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-la-marca', 'la-marca-prosecco', 'La Marca Prosecco', 'La Marca', 'champagne', 'Prosecco', 'Veneto prosecco with pear, apple, and fine bubbles. A Spec''s featured sparkling and an easy brunch bottle.', 'La Marca sources Glera from the Prosecco DOC and bottles a consistent, fruit-forward sparkler for the US market.', 'Veneto, Italy', 'Italy', 11, 750, 15, NULL, 4.4, 4100, '["Pear","Apple","Citrus","Floral"]', '["Brunch","Fruit","Light appetizers"]', '[{"name":"French 75","ingredients":["30ml gin","15ml lemon","10ml syrup","Champagne"],"method":"Shake base, strain into a flute, top with bubbles."},{"name":"Kir Royale","ingredients":["15ml crème de cassis","Champagne"],"method":"Pour cassis in a flute, top with champagne."}]', '["/products/market/la-marca-prosecco.webp"]', '#f3ead2', '#F5E6C8', '#2a2418', 1.2, 0, 1, '["prosecco","everyday","brunch"]', NULL, '/models/bottles/la-marca-prosecco.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-dom-perignon', 'dom-perignon-vintage', 'Dom Pérignon Vintage Champagne', 'Dom Pérignon', 'champagne', 'Vintage Champagne', 'Vintage-only prestige cuvée — toasted brioche, citrus, and a long, precise finish. For the nights that need a statement bottle.', 'Dom Pérignon is Moët''s vintage prestige cuvée, released only in years that meet the chef de cave''s standard.', 'Champagne, France', 'France', 12.5, 750, 220, NULL, 4.8, 860, '["Brioche","Citrus","Mineral","Toast"]', '["Oysters","Caviar","Lobster"]', '[{"name":"French 75","ingredients":["30ml gin","15ml lemon","10ml syrup","Champagne"],"method":"Shake base, strain into a flute, top with bubbles."},{"name":"Kir Royale","ingredients":["15ml crème de cassis","Champagne"],"method":"Pour cassis in a flute, top with champagne."}]', '["/products/market/dom-perignon-vintage.jpg"]', '#f3ead2', '#F5E6C8', '#2a2418', 1.2, 1, 1, '["vintage","prestige","gift","collector"]', NULL, '/models/bottles/dom-perignon-vintage.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-guinness', 'guinness-draught-6pk', 'Guinness Draught 6-Pack Cans', 'Guinness', 'beer', 'Stout', 'Nitrogenated Irish stout — coffee, roasted barley, and that creamy head. The widget can does the pub pour at home.', 'Guinness has been brewed at St. James''s Gate in Dublin since 1759.', 'Dublin, Ireland', 'Ireland', 4.2, 2640, 12, NULL, 4.6, 2700, '["Coffee","Roast","Cream","Chocolate"]', '["Stew","Oysters","Chocolate"]', '[{"name":"Shandy","ingredients":["Beer","Lemon soda"],"method":"Pour half and half over ice or in a pint."}]', '["/products/market/guinness-draught-6pk.jpg"]', '#d4a017', '#D4A017', '#1a1408', 0.78, 0, 1, '["stout","6pk","imported"]', NULL, '/models/bottles/guinness-draught-6pk.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-baileys', 'baileys-original-irish-cream', 'Baileys Original Irish Cream', 'Baileys', 'liqueur', 'Cream Liqueur', 'Irish whiskey and cream — chocolate, vanilla, and coffee. Over ice, in coffee, or as dessert.', 'Baileys launched in 1974 as the original Irish cream and remains the category leader.', 'Ireland', 'Ireland', 17, 750, 24, NULL, 4.6, 4200, '["Cream","Chocolate","Vanilla","Coffee"]', '["Coffee","Ice cream","Dessert"]', '[{"name":"Digestif","ingredients":["45ml liqueur","Ice optional"],"method":"Serve neat or over a single cube."},{"name":"Espresso lift","ingredients":["30ml liqueur","Hot espresso"],"method":"Stir into coffee."}]', '["/products/market/baileys-original-irish-cream.webp"]', '#6b3a6e', '#9B6B9E', '#140814', 0.98, 0, 1, '["cream","dessert","everyday"]', NULL, '/models/bottles/baileys-original-irish-cream.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-baileys-oat', 'baileys-cookies-creamy-oat', 'Baileys Cookies & Creamy Oat Milk', 'Baileys', 'liqueur', 'Non-Dairy Liqueur', 'Oat-milk cookies-and-cream liqueur — dairy-free, dessert-sweet, and a specialty-shop new arrival.', 'Baileys extended the Irish cream idea to oat milk for drinkers who want the cookies-and-cream profile without dairy.', 'Ireland', 'Ireland', 17, 750, 15, 25, 4.3, 210, '["Cookie","Cocoa","Oat","Vanilla"]', '["Coffee","Cookies","Ice cream"]', '[{"name":"Digestif","ingredients":["45ml liqueur","Ice optional"],"method":"Serve neat or over a single cube."},{"name":"Espresso lift","ingredients":["30ml liqueur","Hot espresso"],"method":"Stir into coffee."}]', '["/products/market/baileys-cookies-creamy-oat.png"]', '#6b3a6e', '#9B6B9E', '#140814', 0.98, 0, 1, '["non-dairy","dessert","new"]', NULL, '/models/bottles/baileys-cookies-creamy-oat.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-kahlua', 'kahlua-coffee-liqueur', 'Kahlúa Coffee Liqueur', 'Kahlúa', 'liqueur', 'Coffee Liqueur', 'Rum-based coffee liqueur from Veracruz. Essential for White Russians, espresso martinis, and spiked coffee.', 'Kahlúa has been made with Arabica coffee and rum since 1936 in Mexico.', 'Veracruz, Mexico', 'Mexico', 20, 750, 22, NULL, 4.5, 2800, '["Coffee","Vanilla","Rum","Sugar"]', '["Espresso","Chocolate","Ice cream"]', '[{"name":"Digestif","ingredients":["45ml liqueur","Ice optional"],"method":"Serve neat or over a single cube."},{"name":"Espresso lift","ingredients":["30ml liqueur","Hot espresso"],"method":"Stir into coffee."}]', '["/products/market/kahlua-coffee-liqueur.png"]', '#6b3a6e', '#9B6B9E', '#140814', 0.98, 0, 1, '["coffee","cocktail","everyday"]', NULL, '/models/bottles/kahlua-coffee-liqueur.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-cointreau', 'cointreau-orange-liqueur', 'Cointreau Orange Liqueur', 'Cointreau', 'liqueur', 'Orange Liqueur', 'Crystal-clear triple sec from Angers. Bitter and sweet orange peel — the margarita and Cosmo standard.', 'Cointreau has distilled orange peels in France since 1875 and remains the bartender''s orange liqueur.', 'Angers, France', 'France', 40, 750, 34, NULL, 4.7, 1600, '["Orange peel","Bitter orange","Clean spirit"]', '["Citrus desserts","Chocolate","Cocktails"]', '[{"name":"Digestif","ingredients":["45ml liqueur","Ice optional"],"method":"Serve neat or over a single cube."},{"name":"Espresso lift","ingredients":["30ml liqueur","Hot espresso"],"method":"Stir into coffee."}]', '["https://cdn.shopify.com/s/files/1/0915/6116/5099/files/Cointreau_16c4293f-68ca-4245-b487-aaecf92234e6.png?v=1755800747&width=1200"]', '#6b3a6e', '#9B6B9E', '#140814', 0.98, 0, 1, '["triple-sec","cocktail","essential"]', NULL, '/models/bottles/cointreau-orange-liqueur.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
  ('mk-sarti-rosa', 'sarti-rosa-aperitivo', 'Sarti Rosa Aperitivo', 'Sarti', 'liqueur', 'Aperitivo', 'Italian pink aperitivo with blood orange, mango, and passionfruit. A spritz alternative to Aperol with a fruit-forward line.', 'Sarti Rosa is a contemporary Italian aperitivo built for spritzes and low-proof mixing.', 'Italy', 'Italy', 14, 750, 30, NULL, 4.3, 160, '["Blood orange","Mango","Passionfruit","Bitter"]', '["Prosecco","Fruit","Aperitivo snacks"]', '[{"name":"Digestif","ingredients":["45ml liqueur","Ice optional"],"method":"Serve neat or over a single cube."},{"name":"Espresso lift","ingredients":["30ml liqueur","Hot espresso"],"method":"Stir into coffee."}]', '["/products/market/sarti-rosa-aperitivo.png"]', '#6b3a6e', '#9B6B9E', '#140814', 0.98, 0, 1, '["aperitivo","spritz","new"]', NULL, '/models/bottles/sarti-rosa-aperitivo.glb', NULL, 0, '2026-01-01 00:00:00', '2026-01-01 00:00:00'),
