INSERT INTO `events` (`id`, `slug`, `title`, `type`, `description`, `location_id`, `date`, `start_time`, `end_time`, `price`, `seats_total`, `seats_available`, `image`, `hosts`, `active`) VALUES
  ('e1', 'speyside-evening', 'Speyside Evening: Macallan & Glenfiddich', 'whiskey-tasting', 'A guided tasting through Speyside icons with our whiskey curator. Five pours, cheese pairing, and allocation insights.', 'loc1', '2026-08-15', '19:00', '21:30', 95, 24, 8, '/store/downtown-maison.jpg', '["Marcus Chen"]', 1),
  ('e2', 'champagne-salon', 'Champagne Salon: Dom Pérignon & Beyond', 'wine-tasting', 'Explore vintage Champagne with our uptown concierge. Includes canapés and a take-home tasting journal.', 'loc3', '2026-08-22', '18:30', '21:00', 145, 16, 3, '/store/waterfront-alt.jpg', '["Ava Laurent"]', 1),
  ('e3', 'rum-festival-waterfront', 'Caribbean Rum Festival', 'festival', 'Harbor-side celebration of aged rums, live steel drums, and Diplomático masterclass.', 'loc2', '2026-09-05', '15:00', '21:00', 55, 80, 42, '/store/waterfront-maison.jpg', '["Sofia Alvarez"]', 1),
  ('e4', 'louis-xiii-launch', 'Louis XIII Private Launch Night', 'launch', 'Invitation-style evening unveiling our latest Louis XIII allocation with crystal service.', 'loc3', '2026-09-12', '20:00', '23:00', 350, 12, 2, '/store/downtown-alt.jpg', '["James Whitmore","Ava Laurent"]', 1);
INSERT INTO `reviews` (`id`, `product_id`, `user_name`, `rating`, `title`, `body`, `date`, `verified`, `images`, `helpful`) VALUES
  ('r1', 'mk-blantons', 'David K.', 5, 'Worth every pour', 'Blanton''s Single Barrel is richer than the usual well pour — caramel, spice, and real barrel character. Served neat after dinner.', '2026-06-12', 1, NULL, 48),
  ('r2', 'mk-jw-blue', 'Priya S.', 5, 'Gift that impressed', 'Bought Johnnie Walker Blue Label for my father''s birthday. Silk, smoke, and honey — presentation and taste were flawless.', '2026-05-28', 1, '["/products/market/johnnie-walker-blue-label.webp"]', 31),
  ('r3', 'mk-buffalo-trace', 'Alex M.', 5, 'The classic for a reason', 'Buffalo Trace never disappoints. Vanilla, oak, and enough proof for a proper Old Fashioned.', '2026-07-01', 1, NULL, 67),
  ('r4', 'mk-makers-mark', 'Jordan L.', 4, 'Wheated and easy', 'Maker''s Mark is my go-to neat pour — soft caramel without the rye bite.', '2026-06-20', 1, NULL, 22),
  ('r5', 'mk-wild-turkey-101', 'Claire W.', 5, 'Campfire bourbon', 'Wild Turkey 101 holds up over ice — caramel, spice, and no watery finish.', '2026-01-02', 1, NULL, 55),
  ('r6', 'mk-glenfiddich-12', 'Sam T.', 5, 'Benchmark Speyside', 'Glenfiddich 12 is everything I want in a daily single malt — pear, vanilla, soft spice.', '2026-07-08', 1, NULL, 41);
